                new StatusUpdate { Timestamp = new DateTimeOffset(2026, 6, 10, 10, 45, 0, TimeSpan.Zero), Description = "Delivered", Location = "San Francisco, CA" },
            ]
        },
        ["TRK-003"] = new ShipmentDetails
        {
            TrackingNumber = "TRK-003",
            Status = "Out for Delivery",
            Location = "Austin, TX",
            EstimatedDelivery = new DateTimeOffset(2026, 6, 12, 18, 0, 0, TimeSpan.Zero),
            StatusUpdates =
            [
                new StatusUpdate { Timestamp = new DateTimeOffset(2026, 6, 11, 7, 0, 0, TimeSpan.Zero), Description = "Package picked up", Location = "Dallas, TX" },
                new StatusUpdate { Timestamp = new DateTimeOffset(2026, 6, 11, 22, 0, 0, TimeSpan.Zero), Description = "Arrived at local facility", Location = "Austin, TX" },
                new StatusUpdate { Timestamp = new DateTimeOffset(2026, 6, 12, 8, 0, 0, TimeSpan.Zero), Description = "Out for delivery", Location = "Austin, TX" },
            ]
        },
    };

    public async Task<ShipmentDetails?> GetShipmentAsync(string trackingNumber, CancellationToken ct)
